if (!globalThis.__librarianDiag) {
  const rows = new Map();
  const sinks = new Map();
  const MAX_TAGS = 240;
  const SINK_LIMIT = 3;
  const report = (plugin, tag, err) => {
    try {
      const id = `${plugin}:${tag}`;
      let row = rows.get(id);
      if (!row) {
        if (rows.size >= MAX_TAGS) return;
        row = { plugin, tag, count: 0, firstAt: Date.now(), lastAt: 0, lastMessage: '' };
        rows.set(id, row);
      }
      row.count += 1;
      row.lastAt = Date.now();
      row.lastMessage = String(err?.message ?? err ?? 'unknown').slice(0, 300);
      const sink = sinks.get(plugin);
      if (sink && row.count <= SINK_LIMIT) sink(tag, err);
    } catch (_) {}
  };
  report.registerSink = (plugin, fn) => { try { if (typeof fn === 'function') sinks.set(plugin, fn); } catch (_) {} };
  report.snapshot = () => { try { return [...rows.values()].sort((a, b) => b.count - a.count); } catch (_) { return []; } };
  report.reset = () => { try { rows.clear(); } catch (_) {} };
  globalThis.__librarianDiag = report;
}

