const THEME_KEYS = [
  ['bgcolor', 'bgcolor'], ['darkbg', 'darkbg'], ['borderc', 'borderc'],
  ['selected', 'selected'], ['draculared', 'draculared'],
  ['textcolor', 'textcolor'], ['textcolor2', 'textcolor2'],
  ['darkborderc', 'darkBorderc'], ['darkbutton', 'darkbutton'],
];
const looksLikeColor = value => {
  if (typeof value !== 'string') return false;
  const trimmed = value.trim();
  return trimmed.length >= 3 && trimmed.length <= 64 && /^[#a-zA-Z0-9(),.%\s/-]+$/.test(trimmed);
};
const bridge = {
  applied: false, name: '', type: '', signature: '', lastError: '', pollMs: 0, timer: null,
  resolvers: new Map(),
  // Opt-in. Following the host's COLOURS (as opposed to its light/dark mode and the local
  // reduced-motion preference) replaces each plugin's hand-tuned palette with the host's named
  // greys, which measured worse: elevation inverts because RisuAI's `darkbg` is darker
  // than `bgcolor`, accent saturation drops from 90% to 27%, and HAYAKU's card/background
  // separation falls tenfold. Turn on from a console with:
  //   __memorySuiteTheme.setFollowColors(true)
  followColors: false,
  setFollowColors(on) {
    this.followColors = on === true;
    if (!this.followColors) globalThis.document?.documentElement?.removeAttribute('data-risu-theme-colors');
    this.signature = '';               // force the next apply() to write through
    for (const resolver of this.resolvers.values()) void this.syncOnce(resolver);
    return this.followColors;
  },
  apply(payload) {
    try {
      const scheme = payload && typeof payload === 'object' ? (payload.scheme || payload) : null;
      if (!scheme || typeof scheme !== 'object') { this.lastError = 'empty color scheme'; return false; }
      const pairs = [];
      for (const [suffix, field] of THEME_KEYS) {
        const value = scheme[field] != null ? scheme[field] : scheme[field.toLowerCase()];
        // A partial palette would mix host colours with hardcoded ones, which reads
        // worse than not theming at all. Refuse the whole update instead.
        if (!looksLikeColor(value)) { this.lastError = 'missing colour: ' + field; return false; }
        pairs.push(['--risu-theme-' + suffix, String(value).trim()]);
      }
      const root = globalThis.document && globalThis.document.documentElement;
      if (!root || !root.style) { this.lastError = 'no document root'; return false; }
      const type = String(scheme.type || '') === 'light' ? 'light' : 'dark';
      const signature = JSON.stringify(pairs) + '|' + type + '|' + (this.followColors === true ? 'c' : '-');
      if (signature === this.signature && this.applied) return true;
      for (const [name, value] of pairs) root.style.setProperty(name, value);
      root.setAttribute('data-risu-theme', '1');
      root.setAttribute('data-risu-theme-type', type);
      // The colour-mapping rules are scoped to this second attribute, so light/dark
      // mode is exposed independently of colour mapping. Motion uses a local fallback.
      if (this.followColors === true) root.setAttribute('data-risu-theme-colors', '1');
      else root.removeAttribute('data-risu-theme-colors');
      this.applied = true; this.type = type; this.signature = signature; this.lastError = '';
      this.name = payload && payload.name ? String(payload.name) : '';
      return true;
    } catch (error) {
      this.lastError = String(error && error.message ? error.message : error);
      return false;
    }
  },
  async syncOnce(resolveApi) {
    try {
      const api = typeof resolveApi === 'function' ? resolveApi() : null;
      if (!api || typeof api.getColorScheme !== 'function') { this.lastError = 'getColorScheme unavailable'; return false; }
      return this.apply(await api.getColorScheme());
    } catch (error) {
      this.lastError = String(error && error.message ? error.message : error);
      return false;
    }
  },
  // RisuAI exposes no theme-change event, so a light poll is the only way to follow it.
  // Callers start this when the GUI opens and stop it when the GUI closes.
  start(plugin, resolveApi, intervalMs = 2000) {
    try {
      this.resolvers.set(String(plugin || 'plugin'), resolveApi);
      void this.syncOnce(resolveApi);
      if (this.timer) return true;
      this.pollMs = Math.max(500, Number(intervalMs) || 2000);
      this.timer = setInterval(() => {
        for (const resolver of this.resolvers.values()) void this.syncOnce(resolver);
      }, this.pollMs);
      return true;
    } catch (error) {
      this.lastError = String(error && error.message ? error.message : error);
      return false;
    }
  },
  stop() {
    try { if (this.timer) clearInterval(this.timer); } catch (_) {}
    this.timer = null;
    this.pollMs = 0;
  },
  status() {
    return { applied: this.applied, name: this.name, type: this.type, followColors: this.followColors, pollMs: this.pollMs, lastError: this.lastError };
  },
};
globalThis.__memorySuiteTheme = bridge;

